  function addMessageNode(m,scroll=true){const node=document.createElement('div');node.className='message '+(m.mine?'outgoing':'incoming')+(m.type==='sticker'?' sticker-message':'')+(m.type==='media'?' media-message':'')+(m.type==='voice'?' voice-message':'')+(m.type==='customSticker'?' custom-sticker':'');node.dataset.messageId=m.id||'';if(m.type==='sticker'&&stickerMarkup[m.stickerId]){const art=document.createElement('div');art.className='sent-sticker sent-'+m.stickerId;art.innerHTML=stickerMarkup[m.stickerId];node.appendChild(art)}else if(m.type==='customSticker'&&m.image){const wrap=document.createElement('div');wrap.className='custom-sticker-message';const img=document.createElement('img');img.src=m.image;wrap.appendChild(img);if(m.caption){const cap=document.createElement('strong');cap.textContent=m.caption;wrap.appendChild(cap)}node.appendChild(wrap)}else if(m.type==='media'&&m.url){if(m.mediaType.startsWith('video/')){const video=document.createElement('video');video.src=m.url;video.controls=true;video.playsInline=true;if(m.circle)video.classList.add('video-circle-media');node.appendChild(video)}else{const img=document.createElement('img');img.src=m.url;img.alt='Фото';node.appendChild(img)}}else if(m.type==='voice'&&m.url){const audio=document.createElement('audio');audio.controls=true;audio.src=m.url;if(m.voicePreset==='autotune')audio.playbackRate=1.07;if(m.voicePreset==='deep')audio.playbackRate=.92;if(m.voicePreset==='robot')audio.playbackRate=1.12;node.appendChild(audio);const note=document.createElement('small');note.textContent=m.voicePreset==='autotune'?'✨ AutoTune Pop':m.voicePreset==='deep'?'Deep voice':m.voicePreset==='robot'?'Robot voice':'Оригинальный голос';node.appendChild(note)}else{node.appendChild(document.createTextNode(m.text||''))}if(m.remote&&!m.mine){const sender=document.createElement('small');sender.className='message-sender';sender.textContent=m.senderName||'Участник';node.appendChild(sender)}const time=document.createElement('time');time.textContent=m.time;node.appendChild(time);const del=document.createElement('button');del.type='button';del.className='message-delete';del.textContent='×';del.setAttribute('aria-label','Удалить сообщение');del.addEventListener('click',()=>deleteMessage(m.id));node.appendChild(del);if(m.forwardedFrom){const f=document.createElement('small');f.className='forwarded-label';f.textContent='↪ Переслано из '+m.forwardedFrom;node.prepend(f)}wireMessageHold(node,m);area.appendChild(node);if(scroll)area.scrollTop=area.scrollHeight}
  let holdTimer=null, activeMessageMenu=null;
  function closeMessageMenu(){activeMessageMenu?.remove();activeMessageMenu=null}
  function showMessageMenu(message,node){closeMessageMenu();const menu=document.createElement('div');menu.className='message-action-menu';[['Редактировать','edit'],['Удалить','delete'],['Переслать','forward']].forEach(([label,action])=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',()=>{closeMessageMenu();if(action==='delete'){deleteMessage(message.id);return}if(action==='edit'){if(message.type&&message.type!=='text'){toast('Этот тип сообщения нельзя отредактировать');return}const value=prompt('Измени сообщение:',message.text||'');if(value!==null&&value.trim()){message.text=value.trim();persistMessages();render()}return}const target=activeChatId==='test-1'?'test-2':'test-1';const copy={...message,id:'m-'+Date.now()+'-'+Math.random().toString(16).slice(2),chatId:target,time:clock(),forwardedFrom:chatTitles[activeChatId]};allMessages.push(copy);persistMessages();refreshChatPreview(target);toast('Переслано в '+chatTitles[target])});menu.appendChild(b)});document.body.appendChild(menu);activeMessageMenu=menu;const r=node.getBoundingClientRect();menu.style.left=Math.max(12,Math.min(innerWidth-190,r.left))+'px';menu.style.top=Math.max(12,Math.min(innerHeight-150,r.top-105))+'px'}
  function wireMessageHold(node,message){if(message.remote)return;const open=()=>showMessageMenu(message,node);node.addEventListener('contextmenu',e=>{e.preventDefault();open()});node.addEventListener('touchstart',()=>{holdTimer=setTimeout(open,520)},{passive:true});['touchend','touchmove','touchcancel'].forEach(ev=>node.addEventListener(ev,()=>clearTimeout(holdTimer),{passive:true}));node.addEventListener('mousedown',()=>{holdTimer=setTimeout(open,520)});['mouseup','mouseleave'].forEach(ev=>node.addEventListener(ev,()=>clearTimeout(holdTimer)))}
  function deleteMessage(id){if(!id)return;const found=messages.find(m=>m.id===id);if(found?.remote){toast('Удаление сообщений пока не поддерживается сервером');return}messages=messages.filter(m=>m.id!==id);allMessages=allMessages.filter(m=>m.id!==id);persistMessages();const node=area.querySelector(`[data-message-id=\"${CSS.escape(id)}\"]`);node?.remove();if(!messages.length){const welcome=$('.welcome-message');if(welcome)welcome.style.display='block'}const last=messages[messages.length-1];refreshChatPreview(activeChatId);toast('Сообщение удалено на этом устройстве')}
